const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],el=(t,c,x)=>{const n=document.createElement(t);if(c)n.className=c;if(x!==undefined)n.textContent=x;return n};
const fmt=(x,d=1)=>Number.isFinite(+x)?(+x).toFixed(d):'n/a',pct=(x,d=1)=>fmt(x*100,d)+'%',pp=(x,d=1)=>(x>0?'+':'−')+fmt(Math.abs(x),d)+'%',abs=(x,d=0)=>fmt(Math.abs(x),d);
const load=n=>fetch('data/'+n+'.json').then(r=>r.json());
const C=k=>`<cite data-k="${k}"></cite>`;
const NAMES=['scenario_tree','us_ai_decomposition','china_hidden_debt','scenario_paths','connected_system','contagion','joint_crisis','historical_validation','country_profiles','references','hysteresis','historical_checks','methodology','citations','validation','treasury'];
const PLAIN={continued_boom:['The boom keeps going','Share prices avoid a big fall and keep earning a solid return after inflation.'],no_burst_sideways:['A quiet pause','No big fall, but returns after inflation stay weak for years.'],mild_adjustment:['A modest pullback','Prices drop by about a fifth to a third from a high, then recover some of it.'],moderate_burst:['A sizeable fall','Prices fall by a third to a half from a high.'],deep_drawdown_no_vacuum:['A deep fall, markets keep working','Prices more than halve, but banks and money markets keep functioning.'],severe_burst:['A deep fall and a funding freeze','Prices more than halve and lending between banks, funds and dealers seizes up for a time.'],severe_burst_with_financial_crisis:['A deep fall, a freeze and a banking crisis','As above, and banks need rescuing, so lending to firms and households dries up.']};
const pn=id=>PLAIN[id][0];
const GLOSS=[
 ['hyperscaler',/\bhyperscalers?\b/i,'Hyperscalers','The handful of giant tech companies (such as Amazon, Microsoft, Alphabet and Meta) that rent out huge amounts of computing power and are spending hundreds of billions on AI data centres.'],
 ['margin call',/\bmargin calls?\b/i,'Margin call','When you borrow to buy shares and their price falls, the lender demands extra cash or sells your shares for you.'],
 ['forced sales',/\bforced (?:sales|selling)\b/i,'Forced sales','Selling because you must (to repay a loan or meet a margin call), not because you want to. It pushes prices down further.'],
 ['liquidity vacuum',/\bliquidity vacuum\b/i,'Liquidity vacuum','A moment when buyers and lenders step back at once, so even safe assets can only be sold at a steep discount.'],
 ['liquidity',/\bliquidity\b/i,'Liquidity','How easily something can be sold or borrowed against without moving its price. “Dollar liquidity” is how freely money flows in dollar markets.'],
 ['LGFV',/\bLGFVs?\b/,'LGFV','Local government financing vehicles: companies set up by Chinese cities and provinces to borrow for roads, housing and infrastructure.'],
 ['hysteresis',/\bhysteresis\b/i,'Hysteresis','Lasting damage: after a downturn the economy does not fully return to the path it was on before.'],
 ['peak-to-trough',/\bpeak-to-trough\b/i,'Peak to trough','From the highest price to the lowest price that follows it.'],
 ['real return',/\breal returns?\b/i,'Real return','Investment return after subtracting inflation.'],
 ['Treasury',/\bTreasur(?:y|ies)\b/,'Treasuries','US government bonds: the world’s main “safe” asset.'],
 ['high-yield spread',/\bhigh-yield (?:spread|OAS)\b|\bOAS\b/i,'High-yield spread','The extra interest risky US companies pay over safe government bonds. It widens when lenders get cautious.'],
 ['banking crisis',/\bbanking crises\b|\bbanking crisis\b/i,'Banking crisis','A period when many banks fail or need rescuing and lending to households and firms dries up.'],
 ['stress test',/\bstress[- ]tests?\b/i,'Stress test','A what-if exercise: how would the system cope if a specific bad thing happened? It is not a forecast.'],
 ['run-up',/\brun-ups?\b/i,'Run-up','A big rise in prices over a short period. Here: a gain of 50% or more over three years, after inflation.'],
 ['Brier score',/\bBrier\b/,'Brier score','A score for probability forecasts. Lower is better; always saying “50/50” scores 0.25.'],
 ['base rate',/\bbase rate\b/i,'Base rate','How often something happened overall, ignoring any clues.'],
 ['bootstrap',/\bbootstrap\b/i,'Bootstrap','Re-running the analysis many times on reshuffled samples of history to see how much the answer wobbles.'],
 ['contagion',/\bcontagion\b/i,'Contagion','Trouble spreading from one place or institution to another.'],
 ['safe asset',/\bsafe[- ]assets?\b|\bsafe haven\b/i,'Safe asset','Something investors move money into when they are cautious, expecting it to hold its value.'],
 ['potential growth',/\bpotential growth\b/i,'Potential growth','How fast an economy can grow over the long run without overheating.'],
 ['trend',/\bpre-shock trend\b|\bold path\b|\bbelow trend\b|\bagainst trend\b/i,'Trend','The path the economy was on before the shock. “Below trend” means smaller than it would otherwise have been.'],
 ['debt-deflation',/\bdebt-deflation\b/i,'Debt-deflation','When prices and incomes fall but debts stay fixed, so debts get heavier to carry.'],
 ['capex',/\bcapex\b|\bcapital spending\b/i,'Capex','Capital spending: money firms spend on buildings, chips and equipment.'],
 ['global wave',/\bglobal waves?\b/i,'Global wave','A cluster of booms and busts that hit many countries at about the same time. Each wave counts once, because it is one event, not thirty.'],
 ['AUC',/\bAUC\b/,'AUC','How well a forecast ranks risky cases above safe ones. 0.5 is no better than a coin toss; 1.0 is perfect.'],
 ['percentile',/\bpercentile\b/i,'Percentile band','A range that leaves out the lowest and highest tenth of outcomes.'],
 ['output gap',/\boutput gap\b/i,'Output gap','How far the economy is running below (or above) what it could produce.']];
const SC=(t,id)=>t.scenarios.find(x=>x.id===id),bustOf=t=>1-SC(t,'continued_boom').probability-SC(t,'no_burst_sideways').probability;
const nIn100=x=>Math.round(x*100);

Promise.all(NAMES.map(load)).then(arr=>{
 const D=Object.fromEntries(['tree','us','china','paths','system','cont','joint','history','countries','refs','hyst','checks','meth','cit','val','tic'].map((k,i)=>[k,arr[i]]));
 initModes();renderHero(D);renderShort(D);renderOdds(D);renderTransitionAudit(D.tree);renderChecks(D);renderHeat(D.tree);renderFan(D);renderUS(D);renderChina(D);renderSystem(D);renderEU(D);renderNetwork(D.cont);renderJoint(D);renderHysteresis(D);renderHistory(D);renderEvidence(D);renderCountries(D.countries);renderLimits(D);renderSources(D.refs);renderMethodology(D.meth);renderGlossary();
 const num=numberCitations();renderReferences(D.cit,num);glossarize();initTip()
}).catch(e=>document.body.insertAdjacentHTML('afterbegin','<div class="error">Data load failed: '+e.message+'</div>'));

/* ---------- modes */
function setMode(m){document.body.classList.toggle('simple',m==='simple');document.body.classList.toggle('detailed',m==='detailed');$('#modeSimple').setAttribute('aria-pressed',m==='simple');$('#modeDetail').setAttribute('aria-pressed',m==='detailed');try{localStorage.setItem('gef-mode',m)}catch(e){}}
function initModes(){let m='simple';try{m=localStorage.getItem('gef-mode')||'simple'}catch(e){}setMode(m);$('#modeSimple').onclick=()=>setMode('simple');$('#modeDetail').onclick=()=>setMode('detailed');$$('[data-more]').forEach(b=>b.onclick=()=>{const ch=b.closest('.chapter');setMode('detailed');if(ch)ch.scrollIntoView()})}

/* ---------- hero and summary */
function dotGroups(t){const g=[['boom',SC(t,'continued_boom').probability,'The boom keeps going'],['flat',SC(t,'no_burst_sideways').probability,'A quiet pause'],['fall',SC(t,'mild_adjustment').probability+SC(t,'moderate_burst').probability,'A 20–50% fall'],['deep',SC(t,'deep_drawdown_no_vacuum').probability+SC(t,'severe_burst').probability+SC(t,'severe_burst_with_financial_crisis').probability,'A fall of 50% or more']];const raw=g.map(x=>x[1]*100),base=raw.map(Math.floor);let rest=100-base.reduce((a,b)=>a+b,0);raw.map((v,i)=>[v-Math.floor(v),i]).sort((a,b)=>b[0]-a[0]).slice(0,rest).forEach(([,i])=>base[i]++);return g.map((x,i)=>({k:x[0],n:base[i],label:x[2]}))}
function renderHero({tree,joint,checks,hyst}){
 const bust=bustOf(tree),cal=tree.method.calibration,groups=dotGroups(tree);
 let dots='';groups.forEach(g=>{for(let i=0;i<g.n;i++)dots+=`<i class="d-${g.k}"></i>`});$('#dots').innerHTML=dots;
 $('#dotsLegend').innerHTML=groups.map(g=>`<span><i class="d-${g.k}"></i><b>${g.n}</b> ${g.label}</span>`).join('');
 $('#heroFinding').textContent=`In about ${nIn100(bust)} of 100 futures, AI-linked share prices fall 20% or more before the end of 2030.`;
 $('#heroDetail').innerHTML=`That is what history says too: of past stock booms as big as today’s, about ${nIn100(cal.anchorFall)} in 100 fell by a fifth or more within four years.${C('jstdb,wdi')} Only about ${nIn100(SC(tree,'severe_burst_with_financial_crisis').probability)} in 100 futures here include a banking crisis. A fall in share prices is not the same thing as a crisis.`;
 $('#stamp').innerHTML=['Share prices to 14 Oct 2026','US Treasury holdings to Jul 2026','China debt: IMF, 2025','Window to 31 Dec 2030'].map(x=>`<span>${x}</span>`).join('')}
function renderShort({tree,hyst,checks}){
 const cal=tree.method.calibration,S=hyst.scenarios,u=id=>S[id].us.outputVsTrend2030[1],sy=S.severe_burst_with_financial_crisis;
 const cards=[
  ['1','What we did',`We asked what happens if the AI boom cools. We looked at ${checks.episodes} past stock booms in ${checks.countries} economies, then built a stress test that follows the money from share prices to funding markets, banks, jobs and growth.`],
  ['2','What history says',`After booms as big as today’s, about ${nIn100(cal.anchorFall)} in 100 fell by a fifth or more within four years, and about ${nIn100(SC(tree,'continued_boom').probability)} in 100 kept going. Only ${cal.anchorWaves} independent waves stand behind that, so treat it as a range, not a point.`],
  ['3','What it could mean',`In the middle outcomes the US economy ends 2030 about ${abs(u('mild_adjustment'))}% to ${abs(u('moderate_burst'))}% smaller than it would otherwise have been. In the harshest branch it is about ${abs(u('severe_burst_with_financial_crisis'))}%, with unemployment peaking near ${abs(sy.us.peakUnemployment,0)}%.`],
  ['4','China and Europe',`China is more exposed to a second round because of its property and local-government debt. Europe is hit less: in the harshest branch it ends 2030 about ${abs(sy.eu.outputVsTrend2030[1])}% below its old path, against ${abs(u('severe_burst_with_financial_crisis'))}% for the US and ${abs(sy.china.outputVsTrend2030[1])}% for China.`],
  ['5','How sure are we?',`Not very, and the page says so. In fair tests, clever models did not beat plain history. Fast events inside a single year are blurred. Read these as what-ifs, not forecasts.`]];
 $('#shortGrid').innerHTML=cards.map(c=>`<article><i>${c[0]}</i><h3>${c[1]}</h3><p>${c[2]}</p></article>`).join('');
 $('#calmText').innerHTML=`Think of it as a fire drill, not a fire alarm. Banks run stress tests like this to find weak spots in advance. In this model, outcomes depend a lot on whether funding markets keep working: with markets working, even a deep share-price fall leaves the US economy about ${abs(u('deep_drawdown_no_vacuum'))}% below its old path by 2030; with a freeze and a banking crisis it is about ${abs(u('severe_burst_with_financial_crisis'))}%. That is why central-bank liquidity lines and sound banks matter so much.`}

/* ---------- odds and checks */
function renderOdds({tree,hyst}){const c=$('#odds');tree.scenarios.forEach(s=>{const h=hyst.scenarios[s.id],lv=h.us.outputVsTrend2030[1],r=el('div','odds-row');const cons=s.id==='continued_boom'?'The US economy stays on its old path.':`US economy in 2030: about ${abs(lv,1)}% below its old path; unemployment peaks near ${abs(h.us.peakUnemployment,0)}%.`;r.innerHTML=`<div class="o-name"><b>${pn(s.id)}</b><small>${PLAIN[s.id][1]}</small><small class="cons">${cons}</small><small class="expert">${s.name}: ${s.description}</small></div><progress class="bar" value="${s.probability}" max="1" aria-label="${pn(s.id)}: ${nIn100(s.probability)} in 100"></progress><strong>${nIn100(s.probability)}<em> in 100</em><small>range ${nIn100(s.interval80[0])}–${nIn100(s.interval80[1])}</small></strong>`;c.append(r)});const sel=$('#scenarioSelect');tree.scenarios.forEach(s=>sel.add(new Option(pn(s.id),s.id)))}
function renderTransitionAudit(t){const a=t.method.transitionAudit,p=a.tailShare,cal=t.method.calibration;$('#transitionAudit').innerHTML=`<div><b>${cal.anchorWaves}</b><span>independent global waves among the ${cal.anchorEpisodes} comparable booms (3-year real gain of 100%+)</span></div><div><b>${pct(cal.anchorFall,0)}</b><span>of them fell 20%+ within four years, counting each wave once</span></div><div><b>${a.boomObserved}/${a.boomObserved+a.sidewaysObserved}</b><span>of the no-fall cases kept earning 5%+ a year after inflation</span></div><div><b>${pct(p.systemic,0)}</b><span>of 50%+ falls become banking crises at today’s balance sheets</span></div>`}
function renderChecks({tree,checks}){
 const m=checks.modelWeights,n=checks.nearestAnalogs,b=checks.runupAtLeast100,a=checks.all,cal=tree.method.calibration,iv=b.yearClusterInterval80;
 const bars=[['The seven outcomes above',m.bust,'mint'],['The 25 most similar past booms',n.bust,'amber'],[`Past booms as big as today’s (${cal.anchorWaves} waves)`,cal.anchorFall,'amber'],['All past booms of 50%+',a.bust,'slate'],['A statistical model’s own extrapolation',cal.modelRawFall,'ghost']];
 $('#checkBars').innerHTML=bars.map(x=>`<div class="cbar"><span>${x[0]}</span><div><i class="${x[2]}" style="width:${x[1]*100}%"></i></div><b>${nIn100(x[1])}</b></div>`).join('')+'<p class="legend"><span>Share of cases with a fall of 20% or more, out of 100</span></p>';
 $('#checkTitle').textContent=`History puts a 20%+ fall at about ${nIn100(Math.min(cal.anchorFall,n.bust))}–${nIn100(Math.max(cal.anchorFall,n.bust))} in 100 for booms like this one.`;
 $('#checkPlain').innerHTML=`The seven outcomes sit just above the low end of that range because funding conditions today are tighter than average. We show the model’s own extrapolation (${nIn100(cal.modelRawFall)}) only for comparison: when whole waves of history were held out, it was not reliable enough to use.${C('roberts')} Share prices measured only at year-end miss some falls, so these figures are if anything conservative.`;
 const row=(l,o,x)=>`<tr><th scope="row">${l}<small>${x}</small></th><td>${pct(o.boom,0)}</td><td>${pct(o.sideways,0)}</td><td class="risk-col">${pct(o.bust,0)}</td></tr>`;
 $('#checkTable').innerHTML=`<thead><tr><th></th><th>Boom holds</th><th>Contained</th><th>20%+ fall</th></tr></thead><tbody>${row('Seven outcomes',m,'weights for 2026–2030')}${row(`${n.k} closest run-ups`,n,'nearest on 3-year run-up and last-12-month return')}${row('Run-ups of 100%+',b,`n = ${b.n} · 80% range for the fall ${fmt(iv.bust[0]*100,0)}–${fmt(iv.bust[1]*100,0)}%`)}${row('All run-ups of 50%+',a,`n = ${a.n} · ${checks.countries} economies`)}</tbody>`;
 const bs=b.bySource;
 $('#checkNotes').innerHTML=`<div><b>${pct(b.boom,0)} boom</b><span>${C('greenwood')} Among the ${b.n} run-ups of 100%+, ${pct(b.boom,0)} avoided a 20% peak-to-trough fall and kept earning ${pct(checks.boomHurdle.realPerYear,0)} a year real (80% range ${fmt(iv.boom[0]*100,0)}–${fmt(iv.boom[1]*100,0)}%). An earlier release’s 37% mixed a two-year weight with a 2030 label and measured falls only from the starting level.</span></div><div><b>${pct(bs.modern.bust,0)} vs ${pct(bs.history.bust,0)}</b><span>Share of 100%+ run-ups that ended in a 20% fall: ${bs.modern.n} cases since 1994 versus ${bs.history.n} before.</span></div><div><b>${cal.anchorWaves} waves</b><span>Counting each global wave once leaves ${cal.anchorWaves} independent observations. That is why the ranges are wide.</span></div>`;
 $('#analogList').innerHTML='<p class="eyebrow">Closest historical run-ups</p>'+n.closest.slice(0,8).map(r=>`<div class="analog ${r.outcome}"><b>${r.country} ${r.origin}</b><span>+${fmt(r.runup3*100,0)}% in 3 yrs</span><span>worst fall ${fmt(r.worstDecline*100,0)}%</span><i>${r.outcome==='bust'?'20%+ fall':r.outcome==='boom'?'boom held':'flat'}</i></div>`).join('')}
function riskClass(v){return 'risk-'+Math.max(0,Math.min(9,Math.round(v*9)))}
function renderHeat(t){const c=$('#heatmap');c.className='heat';c.append(el('div','axis',''));['ample liquidity','neutral liquidity','liquidity vacuum'].forEach(x=>c.append(el('div','axis',x)));['calm','tense','crisis'].forEach(g=>{c.append(el('div','axis',g+' geopolitics'));['ample','neutral','vacuum'].forEach(l=>{const r=t.conditionalProbabilities.find(x=>x.geopolitics===g&&x.liquidity===l);const v=Object.entries(r.probabilities).filter(([k])=>!['continued_boom','no_burst_sideways'].includes(k)).reduce((a,[,v])=>a+v,0);const q=el('div','cell '+riskClass(v));q.innerHTML=`<span>${g} × ${l}</span><b>${pct(v,0)}</b><small>${fmt(r.stressMultiplier,2)}× odds</small>`;c.append(q)})});const vac=t.conditionalProbabilities.find(x=>x.geopolitics==='tense'&&x.liquidity==='vacuum').stressMultiplier;$('#heatTitle').textContent=`A liquidity vacuum multiplies the odds of a 20%+ fall by ${fmt(vac,2)}×`}
function renderFan({tree,paths}){const draw=id=>{const rows=paths.scenarios[id].US.gdpGrowth,w=900,h=330,pad=42,ys=[...rows.flatMap(x=>[x.p10,x.p90])],mi=Math.min(...ys)-.3,ma=Math.max(...ys)+.3,x=i=>pad+i*(w-2*pad)/(rows.length-1),y=v=>h-pad-(v-mi)*(h-2*pad)/(ma-mi),poly=[...rows.map((r,i)=>`${x(i)},${y(r.p90)}`),...rows.slice().reverse().map((r,j)=>`${x(rows.length-1-j)},${y(r.p10)}`)].join(' ');$('#fan').innerHTML=`<svg class="chart-svg" viewBox="0 0 ${w} ${h}"><line x1="${pad}" y1="${y(0)}" x2="${w-pad}" y2="${y(0)}" stroke="#466057"/><polygon points="${poly}" fill="rgba(114,241,184,.13)"/><polyline points="${rows.map((r,i)=>`${x(i)},${y(r.p50)}`).join(' ')}" fill="none" stroke="#72f1b8" stroke-width="4"/>${rows.map((r,i)=>`<text x="${x(i)}" y="${h-12}" text-anchor="middle">${r.year}</text><text x="${x(i)}" y="${y(r.p50)-10}" text-anchor="middle">${fmt(r.p50)}%</text>`).join('')}</svg>`;const q=paths.scenarios[id].US,tr=Math.min(0,...q.realGdpIndex.map(r=>r.p50-100)),lv=q.outputVsTrend[4].p50;$('#benchmark').innerHTML=`Typical path: the economy’s deepest dip is ${fmt(Math.abs(tr))}% below 2026, and by 2030 it is ${fmt(Math.abs(lv))}% ${lv<0?'below':'above'} the path it was on before. Shaded band: the middle 80% of simulated paths. ${paths.scenarios[id].benchmark?.text||''}${/severe|deep/.test(id)?C('bea,fedscen'):''}`};$('#scenarioSelect').onchange=e=>draw(e.target.value);draw('severe_burst_with_financial_crisis');$('#scenarioSelect').value='severe_burst_with_financial_crisis'}

/* ---------- United States */
function renderUS({us,system,tic}){
 const mc=us.marketCapShare;
 [[fmt(mc.point)+'%','Core AI-attributed',`of all US company shares · assumption range ${fmt(mc.interval80[0])}–${fmt(mc.interval80[1])}%`],['47.4%','Broad tech and platform group','S&P 500 information technology + communication services'],['73%','Top-10 concentration','inside that combined group']].forEach(v=>{const q=el('div','stat');q.innerHTML=`<b>${v[0]}</b><span>${v[1]}<br>${v[2]}</span>`;$('#usStats').append(q)});
 const core=Math.round(mc.point),broad=47;$('#waffle').innerHTML='<div class="waffle">'+Array.from({length:100},(_,i)=>`<i class="${i<core?'on':i<broad?'broad':''}"></i>`).join('')+`</div><p>${core} squares are the narrow “AI-attributed” share; ${broad-core} more extend to the wider tech and platform group. The wider group is where capex, collateral and earnings carry a shock into credit. It is not a claim that the whole group is a bubble.${C('spdji')}</p>`;
 const pn_=mc.perName,names=Object.keys(pn_).sort((a,b)=>pn_[b].mcapBn-pn_[a].mcapBn);
 $('#exposure').innerHTML=`<h4>How the ${fmt(mc.point)}% is built <span class="kind k-est">Estimated</span></h4><div class="table-wrap"><table><thead><tr><th>Company</th><th>Market value, $bn</th><th>Share counted as AI</th><th>Counted, $bn</th></tr></thead><tbody>${names.map(n=>`<tr><td>${n}</td><td>${fmt(pn_[n].mcapBn,0)}</td><td>${fmt(pn_[n].attributionCentral*100,0)}%</td><td>${fmt(pn_[n].mcapBn*pn_[n].attributionCentral,0)}</td></tr>`).join('')}<tr><th>Total</th><th>${fmt(names.reduce((a,n)=>a+pn_[n].mcapBn,0),0)}</th><th></th><th>${fmt(mc.numeratorBn,0)}</th></tr></tbody></table></div><p class="caveat">Prices of ${mc.priceDate}. Denominator: all US corporate equities ($${fmt(mc.denominatorBn/1000,1)}tn, Fed Z.1 of ${mc.rollForwardDetail.stockDateUsed}, rolled forward with the S&amp;P 500 and scaled by f = ${mc.fCentral}). The “share counted as AI” is an assumption: platforms that sell much more than AI are given 35%, chip-makers 50–90%. The range ${fmt(mc.interval80[0])}–${fmt(mc.interval80[1])}% uses the low and high attribution cases; ${fmt(mc.intervalFull[0])}–${fmt(mc.intervalFull[1])}% also varies f from ${mc.fScaling[0]} to ${mc.fScaling[1]}.</p>`;
 const q=system.scenarios.severe_burst_with_financial_crisis,mn=a=>Math.min(...a.map(x=>x.p50)),mx=a=>Math.max(...a.map(x=>x.p50));
 const steps=[['Expectations reset',`Expected AI revenue falls short of what the spending commitments need. Cash cover for those commitments falls from 1.65× to ${fmt(mn(q.cashFlowCoverage),2)}×.`],['Borrowing gets dearer',`Hyperscaler borrowing costs rise from about 5% to ${fmt(mx(q.hyperscalerMarginalRate))}% while the commitments stay fixed.`],['Selling feeds on itself',`Margin calls and forced sales take the US stock-price index to ${fmt(mn(q.usEquityIndex),0)} (today = 100) at the low point.`],['The real economy feels it',`Unemployment peaks near ${fmt(mx(q.usUnemployment),0)}%; output ends 2030 ${fmt(Math.abs(q.usOutputVsTrend[4].p50),0)}% below its old path.`]];
 $('#usChain').innerHTML=steps.map((s,i)=>`<i>${i+1}</i><p><b>${s[0]}</b><span>${s[1]}${i===0?C('aischool,jcurve,bisai'):i===2?C('bp09,km97'):''}</span></p>`).join('');
 const J=tic.holders[0],Cn=tic.holders[1],mlabel=m=>new Date(m+'-01').toLocaleString('en',{month:'long',year:'numeric'});
 $('#treasury').innerHTML=`<div class="tre"><div><b>$${fmt(J.latest/1000,3)}tn</b><span>Japan · ${mlabel(tic.latestMonth)} (${fmt(J.latest/tic.grandTotal.latest*100,1)}% of foreign holdings)</span></div><div><b>$${fmt(Cn.latest/1000,3)}tn</b><span>China mainland · ${mlabel(tic.latestMonth)} (${fmt(Cn.latest/tic.grandTotal.latest*100,1)}%)</span></div></div>`;
 $('#treasuryNote').innerHTML=`Two big holders of US government bonds could, in theory, sell in a crisis. That is capacity, not intent, and holdings are recorded by where the custodian is, so a bond can belong to someone elsewhere. Selling would not automatically destabilise the market either: dealers, the Fed and other buyers can absorb it. The model treats sales only as a stress trigger when dealer balance sheets are already strained. Holdings were $${fmt(J.prior/1000,3)}tn and $${fmt(Cn.prior/1000,3)}tn in ${mlabel(tic.priorMonth)}.${C('tic,cfg16')}`}

/* ---------- China */
function renderChina({china}){const pr=china.measuredProxies||[],find=s=>pr.find(x=>x.label.includes(s)),pick=[find('Credit-to-GDP ratio'),find('property index fall'),find('Augmented debt')].filter(Boolean);
 pick.forEach(x=>{const s=el('div','stat');s.innerHTML=`<b>${fmt(x.value)}${x.unit.includes('percent')?'%':''}</b><span>${x.label}<br>${x.asOf}</span>`;$('#chinaStats').append(s)});
 const off=find('Gross general budgetary'),aug=find('Augmented debt, IMF perimeter'),proj=(china.policySpace||[]).find(x=>/Augmented debt/.test(x.item));
 $('#chinaDebtLine').innerHTML=`official budget debt was about ${fmt(off.value,0)}% of GDP in 2025, while the IMF’s wider “augmented” measure, which adds local-government vehicles and similar items, was about ${fmt(aug.value,0)}% in 2025 and is projected near ${fmt(proj.value,0)}% for 2026.${C('imfchn,bisgap,chen')}`;
 const comps=china.components.filter(x=>x.low!=null),max=Math.max(...comps.map(x=>x.high));$('#debtRanges').innerHTML=comps.map(x=>`<div class="debt-row"><b>${x.name}</b><svg class="range" viewBox="0 0 100 12" preserveAspectRatio="none" role="img" aria-label="${fmt(x.low,0)} to ${fmt(x.high,0)} ${x.unit}"><rect class="range-bg" x="0" y="0" width="100" height="12" rx="6"/><rect class="range-band" x="${x.low/max*100}" y="0" width="${Math.max(2,(x.high-x.low)/max*100)}" height="12" rx="6"/></svg><span>${fmt(x.low,0)}–${fmt(x.high,0)} ${x.unit}</span></div>`).join('')}

/* ---------- Europe */
function renderEU({paths,hyst}){
 const s=hyst.scenarios.severe_burst_with_financial_crisis,eu=s.eu.outputVsTrend2030[1],us=s.us.outputVsTrend2030[1],cn=s.china.outputVsTrend2030[1];
 $('#euLede').innerHTML=`Europe’s listed companies are mostly conventional industry, banks and consumer firms, not AI platforms, and Europe does not carry a China-style property-debt overhang. In the harshest branch the euro-area economy ends 2030 about ${abs(eu,1)}% below its old path, against ${abs(us,1)}% for the US and ${abs(cn,1)}% for China. If the US and China both come out weakened, Europe is the large economy least damaged, and it is also pushing towards energy and critical-materials independence.${C('crma')}`;
 const q=paths.scenarios.severe_burst_with_financial_crisis;
 lineChart($('#euCompare'),[['US','#ff9f6b',q.US],['China','#e9c46a',q.China],['Euro area','#72f1b8',q.EU]].map(([n,c,r])=>({color:c,points:r.outputVsTrend.map((x,i)=>({x:i,y:x.p50})),label:v=>n+' '+pp(v)})),{zero:0,xticks:[0,1,2,3,4],xlabel:v=>2026+v,h:300});
 $('#euNote').innerHTML=`On this measure Europe ends ${fmt(Math.abs(us)-Math.abs(eu),1)} points ahead of the US and ${fmt(Math.abs(cn)-Math.abs(eu),1)} ahead of China. The model includes the first-round hit and a small rebound term; it does <b>not</b> simulate money flowing into euro assets or any shift in the euro’s global role. Those are scenario judgments.`}

/* ---------- joint */
function renderJoint({joint:j}){const q=j.probabilityCurrentTrajectory,m=j.marginals,g=j.reverseStress;
 $('#jointText').innerHTML=`The worst case needs both problems at once. In the model that happens in about ${nIn100(q.point)} of 100 futures. The two are linked: when the US has a banking crisis, China is in trouble too in about ${nIn100(m.chinaCrisisConditionalOnUsSystemic)} of 100 cases, because dollar funding tightens and money leaves. When China has a crisis, the US does in about ${nIn100(m.usSystemicConditionalOnChinaCrisis)} of 100.${C('forbes,embrechts')}`;
 $('#jointStat').innerHTML=`<div class="joint-number">${nIn100(q.point)}<em> in 100</em></div><p>Both stress flags by 31 Dec 2030. Range (10th–90th percentile) ${nIn100(q.interval80[0])}–${nIn100(q.interval80[1])}.</p>`;
 $('#jointMarginals').innerHTML=[['US banking crisis',m.usSystemic],['China crisis',m.chinaCrisis],['China, given a US crisis',m.chinaCrisisConditionalOnUsSystemic],['US, given a China crisis',m.usSystemicConditionalOnChinaCrisis]].map(x=>`<div><b>${nIn100(x[1])}<em>/100</em></b><span>${x[0]}</span></div>`).join('');
 $('#jointNote').innerHTML=`One check on the arithmetic: US crisis ${pct(m.usSystemic)} × China given US ${pct(m.chinaCrisisConditionalOnUsSystemic)} = ${pct(m.usSystemic*m.chinaCrisisConditionalOnUsSystemic)}, and China ${pct(m.chinaCrisis)} × US given China ${pct(m.usSystemicConditionalOnChinaCrisis)} = ${pct(m.chinaCrisis*m.usSystemicConditionalOnChinaCrisis)}. Both give the same joint figure. It cannot exceed the US figure, because the US banking-crisis flag comes from the AI-reset scenarios. A China-first crisis that spreads to the US is outside this model and would add to it.`;
 const f=$('#frontier');f.className='frontier';f.style.gridTemplateColumns=`36px repeat(${g.x.values.length},minmax(0,1fr))`;f.append(el('i','axis-cell',''));g.x.values.forEach(v=>f.append(el('i','axis-cell',v)));g.y.values.forEach((yv,yi)=>{f.append(el('i','axis-cell',yv+'%'));g.values[yi].forEach(v=>{const i=el('i',riskClass(v));i.innerHTML=`<b>${fmt(v*100,0)}</b>`;i.title=`Conditional joint risk ${pct(v)}`;f.append(i)})});
 $('#thresholds').innerHTML=j.boundaryConditions.map(x=>`<div class="threshold"><small>Stress boundary</small><b>${x.displayThreshold||x.threshold}</b><p>${x.variable}</p><span>Current ${x.displayCurrent||x.currentValue}</span></div>`).join('');
 $('#connections').innerHTML=`<p class="eyebrow">Same simulated paths</p><p>US systemic ${pct(m.usSystemic)} · China ${pct(m.chinaCrisis)} · either ${pct(m.eitherCrisis)} · both ${pct(q.point)} (80% range ${pct(q.interval80[0])}–${pct(q.interval80[1])}).</p>`}
function renderSystem({tree,system:d}){const sel=$('#systemSelect');tree.scenarios.forEach(x=>sel.add(new Option(pn(x.id),x.id)));const draw=id=>{const q=d.scenarios[id],vars=[['AI revenue expectations',q.aiRevenueExpectations,'index'],['US equity',q.usEquityIndex,'2026=100'],['Margin calls',q.marginCallPressure,'index'],['Liquidity stress',q.liquidityStress,'index'],['Hyperscaler funding',q.hyperscalerMarginalRate,'%'],['Cash-flow coverage',q.cashFlowCoverage,'×'],['China outflow stress',q.chinaCapitalOutflow,'index'],['LGFV refinancing',q.lgfvRefinancingRate,'%']];const f=(v,u)=>fmt(v,u==='index'?2:1)+(u==='%'||u==='2026=100'?u:' '+u);$('#systemGrid').innerHTML=vars.map(([n,r,u])=>`<div class="system-card"><span>${n}</span><b>${f(r[1].p50,u)}</b><small>2027 median → 2030 ${f(r[4].p50,u)}</small><i style="--w:${Math.min(100,Math.max(2,(r[1].p50/(u==='%'?12:u==='2026=100'?100:u==='×'?2:1))*100))}%"></i></div>`).join('')};sel.onchange=e=>draw(e.target.value);sel.value='severe_burst_with_financial_crisis';draw(sel.value);$('#feedbackLoops').innerHTML=d.feedbackLoops.map((x,i)=>`<div><b>0${i+1}</b><span>${x}</span></div>`).join('')}
function renderNetwork(d){let nodes=(d.nodes||[]).slice(0,10),edges=(d.edges||[]).slice(0,16);if(!nodes.length){nodes=['US equity','US credit','Repo','USD funding','EU banks','CHF/SNB','Japan carry','China debt','EM','Commodities'].map((label,i)=>({id:'n'+i,label}));edges=nodes.slice(1).map((n,i)=>({from:nodes[i].id,to:n.id}))}const pos=nodes.map((n,i)=>({n,x:450+310*Math.cos(i/nodes.length*6.28-1.57),y:250+190*Math.sin(i/nodes.length*6.28-1.57)})),map=Object.fromEntries(pos.map(x=>[x.n.id,x]));const svg=$('#network');svg.innerHTML=edges.filter(e=>map[e.from]&&map[e.to]).map(e=>`<path class="edge" d="M${map[e.from].x},${map[e.from].y} L${map[e.to].x},${map[e.to].y}"/>`).join('')+pos.map(({n,x,y})=>`<g class="node"><circle cx="${x}" cy="${y}" r="34"/><text x="${x}" y="${y+4}" text-anchor="middle">${(n.label||n.id).slice(0,13)}</text></g>`).join('')}

/* ---------- charts */
function lineChart(target,series,o={}){
 const w=o.w||860,h=o.h||320,pad=48,xs=series.flatMap(s=>s.points.map(p=>p.x)),ys=series.flatMap(s=>s.points.map(p=>p.y)),xmin=Math.min(...xs),xmax=Math.max(...xs),lo=Math.min(...ys,o.floor??1e9)-1,hi=Math.max(...ys,o.ceil??-1e9)+1;
 const X=v=>pad+(v-xmin)*(w-2*pad)/(xmax-xmin||1),Y=v=>h-pad-(v-lo)*(h-2*pad)/(hi-lo||1);
 const zero=o.zero!==undefined?`<line x1="${pad}" y1="${Y(o.zero)}" x2="${w-pad}" y2="${Y(o.zero)}" stroke="#466057"/>`:'';
 const ticks=(o.xticks||[...new Set(xs)]).map(v=>`<text x="${X(v)}" y="${h-14}" text-anchor="middle">${o.xlabel?o.xlabel(v):v}</text>`).join('');
 const lines=series.map(s=>`<polyline points="${s.points.map(p=>`${X(p.x)},${Y(p.y)}`).join(' ')}" fill="none" stroke="${s.color}" stroke-width="${s.w||4}" ${s.dash?`stroke-dasharray="${s.dash}"`:''}/>${s.dots===false?'':s.points.map(p=>`<circle cx="${X(p.x)}" cy="${Y(p.y)}" r="4" fill="${s.color}"/>`).join('')}${s.label?`<text x="${X(s.points.at(-1).x)-6}" y="${Y(s.points.at(-1).y)-10}" text-anchor="end" style="fill:${s.color}">${s.label(s.points.at(-1).y)}</text>`:''}`).join('');
 target.innerHTML=`<svg class="chart-svg" viewBox="0 0 ${w} ${h}">${zero}${ticks}${lines}</svg>`}

/* ---------- hysteresis */
function renderHysteresis({tree,paths,hyst}){
 const sysS=hyst.scenarios.severe_burst_with_financial_crisis,us=sysS.us,cn=sysS.china,sel=$('#hystSelect');
 tree.scenarios.forEach(s=>sel.add(new Option(pn(s.id),s.id)));
 $('#hystLede').innerHTML=`Even after growth recovers, the economy can stay below the path it was on. In the harshest branch US output is about ${abs(us.outputVsTrend2030[1])}% below its old path in 2030 and still about ${abs(us.outputVsTrend2036NoNewShock)}% below in 2036 if nothing else goes wrong. China is about ${abs(cn.outputVsTrend2030[1])}% below in 2030 and ${abs(cn.outputVsTrend2036NoNewShock)}% in 2036. Credit that is not extended, investment that is cancelled and workers who drift out of work do not come back with the next upswing.${C('cerra,bcs,rww')}`;
 $('#hystTitle').textContent=`Growth returns to about ${fmt(paths.scenarios.severe_burst_with_financial_crisis.US.gdpGrowth[4].p50,0)}% by 2030. The gap does not close.`;
 const ch=(el_,items,share)=>{el_.innerHTML=items.map(c=>`<div class="channel"><span>${c.label}<small>${c.driver}</small></span><i style="--w:${Math.round((share[c.id]||0)*100)}%"></i><b>${fmt((share[c.id]||0)*100,0)}%</b></div>`).join('')};
 const draw=id=>{const h=hyst.scenarios[id],u=h.us,c=h.china,q=paths.scenarios[id];
  const lv=r=>q[r].outputVsTrend.map((x,i)=>({x:i,y:x.p50})),ext=(r,e)=>[{x:4,y:q[r].outputVsTrend[4].p50},{x:10,y:e}];
  lineChart($('#hystChart'),[{color:'#ff9f6b',points:lv('US'),label:v=>'US '+pp(v)},{color:'#ff9f6b',w:2,dash:'4 6',dots:false,points:ext('US',u.outputVsTrend2036NoNewShock)},{color:'#e9c46a',points:lv('China'),label:v=>'China '+pp(v)},{color:'#e9c46a',w:2,dash:'4 6',dots:false,points:ext('China',c.outputVsTrend2036NoNewShock)}],{zero:0,xticks:[0,1,2,3,4,10],xlabel:v=>v<5?2026+v:'2036'});
  $('#hystLegend').innerHTML='<span>Solid: typical path to 2030</span><span>Dotted: 2036 if no new shock hits</span>';
  const stat=(b,t)=>`<div><b>${b}</b><span>${t}</span></div>`;
  $('#hystUS').innerHTML=stat(pp(u.outputVsTrend2030[1]),'output vs its old path, 2030')+stat(pp(u.outputVsTrend2036NoNewShock),'in 2036, no new shock')+stat(fmt(u.potentialGrowth2030,1)+'%','long-run speed in 2030 (before: 2.4%)')+stat(u.firstYearLossAbove1pct||'—','first year lasting loss tops 1%');
  $('#hystCN').innerHTML=stat(pp(c.outputVsTrend2030[1]),'output vs its old path, 2030')+stat(pp(c.outputVsTrend2036NoNewShock),'in 2036, no new shock')+stat(fmt(c.potentialGrowth2030,1)+'%',`long-run speed in 2030 (before: ${fmt(c.baselineGrowth2030,1)}%)`)+stat(c.firstYearLossAbove1pct||'—','first year lasting loss tops 1%');
  const flag=(x,m)=>x.permanentLoss2030>1?m:{};
  ch($('#hystUSChannels'),hyst.channels.US,flag(u,u.channelShare));ch($('#hystCNChannels'),hyst.channels.China,flag(c,c.channelShare))};
 sel.onchange=e=>draw(e.target.value);sel.value='severe_burst_with_financial_crisis';draw(sel.value);
 const v=hyst.validation,m=v.modelSystemicUS,hs=v.historicalSameClass,rows=[['10th percentile',m.p10,hs.p10],['25th percentile',m.p25,hs.p25],['Median',m.p50,hs.p50]],mi=Math.min(...rows.flatMap(r=>[r[1],r[2]]));
 $('#hystValTitle').textContent=`Model against ${hs.n} comparable banking crises`;
 $('#hystVal').innerHTML=rows.map(r=>`<div class="vrow"><span>${r[0]}</span><div><i class="mod" style="width:${Math.abs(r[1]/mi)*100}%"></i><i class="his" style="width:${Math.abs(r[2]/mi)*100}%"></i></div><b>${pp(r[1])} / ${pp(r[2])}</b></div>`).join('')+'<p class="legend"><span class="m">Model, systemic branch</span><span class="h">History: 4 years after a 35%+ equity fall with a banking crisis</span></p>';
 const g=v.gfcUS[0];$('#hystValNote').innerHTML=`US 2008 crisis: ${pp(g.h3)} after 3 years, ${pp(g.h5)} after 5, ${pp(g.h7)} after 7. Output is real GDP per head against the ten-year pre-crisis trend; 1900–2016, war years excluded.${C('jstdb,rr')}`;
 const sens=hyst.cohorts.japanSensitivity.filter(x=>x.trendYears!=='1960–1989'),r4=[Math.min(...sens.map(x=>x.h4)),Math.max(...sens.map(x=>x.h4))],r10=[Math.min(...sens.map(x=>x.h10)),Math.max(...sens.map(x=>x.h10))],jp=hyst.cohorts.japanAfter1989.filter(x=>x.yearsAfter<=20).map(x=>({x:x.yearsAfter,y:x.shortfall}));
 $('#japanTitle').textContent=`Japan after 1989: ${abs(r4[1])}–${abs(r4[0])}% below its old path at year four, ${abs(r10[1])}–${abs(r10[0])}% at year ten.`;
 const cnp=hyst.systemicMedianPath.China.level.map((y,i)=>({x:i,y})).concat([{x:10,y:cn.outputVsTrend2036NoNewShock}]);
 lineChart($('#japanChart'),[{color:'#e9c46a',points:jp,dots:false,label:v=>'Japan '+pp(v)},{color:'#ff9f6b',points:cnp,label:v=>'China model '+pp(v)}],{zero:0,xticks:[0,5,10,15,20],xlabel:v=>'+'+v+' y'});
 $('#japanNote').innerHTML=`The “old path” is the 1980–89 trend of real GDP per head; using 1970–89 or 1975–89, or total instead of per-head GDP, gives the ranges above. Part of Japan’s later slowdown reflects its ageing population, so not all of it is crisis damage. China’s model path is anchored to Japan’s ten-year shortfall (${pp(hyst.calibration.japanTarget10y)}); one analogue means wider uncertainty.${C('hoshi,koo')}`;
 $('#hystIndicators').innerHTML='<thead><tr><th>Economy</th><th>Gauge</th><th>Now</th><th>Watch level</th><th>Why it matters</th></tr></thead><tbody>'+hyst.indicators.map(i=>`<tr><td>${i.economy}</td><td>${i.indicator}</td><td>${fmt(i.now,i.now%1===0?0:1)} ${i.unit}</td><td>${i.watch==null?'—':i.watch}</td><td>${i.meaning}</td></tr>`).join('')+'</tbody>'}

function renderHistory({history:h,hyst}){const sel=$('#historySelect'),model=h.analogs.find(x=>x.id==='model_systemic_2026');h.analogs.filter(x=>x.id!==model.id).forEach(a=>sel.add(new Option(a.label,a.id)));const draw=id=>{const a=h.analogs.find(x=>x.id===id),series=[a,model],w=860,hg=320,pad=52,vals=[...series.flatMap(s=>s.realGdpIndex.map(x=>x.value)),...model.trendIndex.map(x=>x.value)],mi=Math.min(...vals)-1,ma=Math.max(...vals)+1,x=i=>pad+i*(w-2*pad)/(Math.max(...series.map(s=>s.realGdpIndex.length))-1),y=v=>hg-pad-(v-mi)*(hg-2*pad)/(ma-mi);$('#historyChart').innerHTML=`<svg class="chart-svg" viewBox="0 0 ${w} ${hg}"><line x1="${pad}" y1="${y(100)}" x2="${w-pad}" y2="${y(100)}" stroke="#466057"/><polyline points="${model.trendIndex.map((z,i)=>`${x(i)},${y(z.value)}`).join(' ')}" fill="none" stroke="#94aaa1" stroke-width="2" stroke-dasharray="4 6"/>${series.map((s,j)=>`<polyline points="${s.realGdpIndex.map((z,i)=>`${x(i)},${y(z.value)}`).join(' ')}" fill="none" stroke="${j?'#ff9f6b':'#72f1b8'}" stroke-width="4"/>${s.realGdpIndex.map((z,i)=>`<circle cx="${x(i)}" cy="${y(z.value)}" r="4" fill="${j?'#ff9f6b':'#72f1b8'}"/>`).join('')}`).join('')}</svg><p class="legend"><span>${a.label} · green</span><span>Model, harshest path · orange</span><span>2.4% trend · dotted</span></p>`;$('#historyNote').textContent=`${a.label}: ${a.yearsNegative} year(s) of falling output, ${fmt(a.cumulativeGrowth)}% cumulative change. Model: ${model.yearsNegative} year(s) of falling output, ${fmt(model.cumulativeGrowth)}% cumulative change. ${h.limitations}`};sel.onchange=e=>draw(e.target.value);sel.value='us_gfc';draw('us_gfc');$('#historySummary').innerHTML=h.analogs.slice(0,-1).map(a=>`<div class="score"><span>${a.label}</span><b>${a.yearsNegative} year${a.yearsNegative===1?'':'s'} down</b></div>`).join('');
 const b=hyst.imfBenchmark,ours=b.ours,ids=['no_burst_sideways','mild_adjustment','moderate_burst','deep_drawdown_no_vacuum','severe_burst_with_financial_crisis'],mx=Math.max(...ids.map(i=>Math.abs(ours[i].usOutputVsBaseline2028)),1.8);
 $('#imfBench').innerHTML=`<p class="plain">The IMF’s October 2026 outlook includes a case where AI payoffs disappoint, investment pulls back and markets correct. It puts US GDP about ${abs(b.adverseAI.usGdp2028,1)}% below baseline by 2028 (global: ${abs(b.adverseAI.globalGdp2028,1)}%).${C('imfweo')} That is a market correction with tighter finance, not a banking crisis. It sits between our “quiet pause” and “modest pullback”; our harsher branches add forced selling and bank stress.</p>`+`<div class="imf">${ids.map(i=>`<div class="cbar"><span>${pn(i)}</span><div><i class="amber" style="width:${Math.abs(ours[i].usOutputVsBaseline2028)/mx*100}%"></i></div><b>${abs(ours[i].usOutputVsBaseline2028,1)}%</b></div>`).join('')}<div class="cbar"><span><em>IMF adverse AI case</em></span><div><i class="mint" style="width:${1.8/mx*100}%"></i></div><b>1.8%</b></div></div><p class="caveat">US output below its baseline path in 2028, in %. IMF figures as reported by Reuters on 13 Oct 2026; the primary scenario chapter was not retrieved. Our outcomes measure output against the pre-shock trend, which is comparable in spirit but not identical.</p>`}

/* ---------- evidence */
function renderEvidence({val,tree}){
 const wv=val.validation.schemes['Leave one global wave out'],fb='Full blend (logit + boosting + forest)',bs='Base rate (training frequency)',ec=val.engineChecks,sr=val.samplingResolution,rel=wv[fb].reliability;
 $('#evidencePlain').innerHTML=`We tried four statistical models of whether a boom ends in a 20% fall and tested them the hard way: hold out an entire wave of history, then predict it. The best model only slightly beat a simple “what happened last time” rule, and its ranking of risky versus safe cases was no better than a coin toss (AUC ${fmt(wv[fb].auc,2)}). So the headline odds rest on history itself, and the models are shown for comparison.${C('roberts,brier')}`;
 const names=Object.keys(wv),mx=Math.max(...names.map(n=>wv[n].brier));$('#evidenceBars').innerHTML='<p class="eyebrow">Forecast error when whole waves are held out (lower is better)</p>'+names.map(n=>`<div class="cbar"><span>${n.replace(' (training frequency)','').replace(' (ridge logit)','')}</span><div><i class="${n===bs?'slate':'amber'}" style="width:${wv[n].brier/mx*100}%"></i></div><b>${fmt(wv[n].brier,3)}</b></div>`).join('');
 const ec_=val.validation.schemes['Leave one economy out'];
 $('#valTable').innerHTML=`<thead><tr><th>Forecast</th><th>Brier, waves out</th><th>Log loss</th><th>AUC</th><th>Brier, economies out</th><th>AUC</th></tr></thead><tbody>${names.map(n=>`<tr><td>${n}</td><td>${fmt(wv[n].brier,3)}</td><td>${fmt(wv[n].logLoss,3)}</td><td>${wv[n].auc?fmt(wv[n].auc,2):'n/a'}</td><td>${fmt(ec_[n].brier,3)}</td><td>${ec_[n].auc?fmt(ec_[n].auc,2):'n/a'}</td></tr>`).join('')}</tbody>`;
 const ot=val.validation.outOfTime;$('#valNote').innerHTML=`Target: a 20%+ peak-to-trough fall within four annual closes. ${val.validation.waveCount} global waves. Out of time: ${Object.entries(ot).map(([k,v])=>`${k.toLowerCase()}: blend ${fmt(v.models[fb].brier,3)} vs base ${fmt(v.models[bs].brier,3)}`).join('; ')}. An AUC of 0.5 is chance.${C('gneiting')}`;
 $('#reliab').innerHTML=rel.map(b=>`<div class="rel"><span>said ${nIn100(b.predicted)}</span><div><i class="pred" style="width:${b.predicted*100}%"></i><i class="obs" style="width:${b.observed*100}%"></i></div><b>happened ${nIn100(b.observed)}</b></div>`).join('')+'<p class="legend"><span class="m">Predicted</span><span class="h">Observed</span></p><p class="caveat">Held-out waves, five equal-sized groups. A well-calibrated forecast has equal bars.</p>';
 $('#sensTable').innerHTML='<thead><tr><th>Variant</th><th>Fall</th><th>Boom</th><th>n</th></tr></thead><tbody>'+val.sensitivity.map(r=>`<tr><td>${r.variant}</td><td>${nIn100(r.fall20)}</td><td>${nIn100(r.boom)}</td><td>${r.episodes}</td></tr>`).join('')+'</tbody>';
 $('#resolution').innerHTML=`<p>${sr.source}. Of ${sr.windows} four-year windows, <b>${pct(sr.monthlyFall20,0)}</b> contain a 20% peak-to-trough fall in monthly data but only <b>${pct(sr.annualFall20,0)}</b> at annual closes. Annual closes catch ${pct(sr.annualCatchesMonthlyFalls,0)} of the falls monthly data see and understate their depth by a median ${fmt(sr.medianDepthUnderstatedPp,0)} points. After 3-year gains of 50%+, the figures are ${pct(sr.afterRunup50.monthlyFall20,0)} vs ${pct(sr.afterRunup50.annualFall20,0)} (n = ${sr.afterRunup50.windows}). Every fall probability here is therefore conservative.${C('shiller')}</p>`;
 $('#engineChk').innerHTML=`<p>The finance engine solves one shared state per year. Same shocks, 40 versus 60 iterations, and starts from liquidity 0 and 1 give the same answer: largest remaining residual ${ec.worstResidualAfter8.toFixed(4)}, multiple equilibria in ${pct(ec.worstMultiEquilibriumShare,0)} of paths. The state moves once a year, so events inside a year, such as margin calls over days, are collapsed into one step. A higher-frequency contagion layer is the main modelling gap.</p>`}
function renderCountries(d){for(const [name,c] of Object.entries(d.countries)){const m=c.metrics,r=el('tr');const f=v=>v==null?'n/a':fmt(v)+'%';r.innerHTML=`<td><b>${name}</b><small>${c.summary}</small></td><td>${f(m.growth)}</td><td>${f(m.publicDebt)}</td><td>${f(m.privateCredit)}</td><td>${f(m.policyRate)}</td><td>${m.directExposure}</td><td>${c.shockRole}</td>`;$('#countryGrid').append(r)}}
function renderLimits({tree,val}){const cal=tree.method.calibration;
 $('#limits').innerHTML=[`<b>It is a what-if, not a forecast.</b> It does not say when, or whether, anything will happen.`,`<b>Few comparable booms exist.</b> About ${cal.anchorWaves} independent waves stand behind the odds, so every number carries a wide range.`,`<b>Fast events are blurred.</b> The model moves once a year, and year-end prices miss falls inside the year (about ${nIn100(1-val.samplingResolution.annualCatchesMonthlyFalls)} in 100 US 20% falls in monthly data).`,`<b>Only an AI-led shock is simulated.</b> Energy shocks, rising bond yields and wars can interact with it; the IMF lists them separately. Here they enter only through the funding-conditions setting.`,`<b>China rests on one comparison (Japan), and Europe’s safe-asset upside is a judgment, not a result.</b>`,`<b>Policy responses are simplified.</b> Central-bank and government support beyond one liquidity term is not simulated.`,`<b>Not investment advice.</b> Nothing here says what to buy or sell.${C('sr117')}`].map(x=>`<li>${x}</li>`).join('');
 const c=tree.method.challengerBustProbabilities,v=tree.method.transitionAudit.systemicTransition.validation;
 $('#scorecard').innerHTML=`<div class="score"><span>Headline: 20%+ fall, comparable booms</span><b>${pct(cal.anchorFall,0)}</b></div><div class="score"><span>Model extrapolation (not used)</span><b>${pct(cal.modelRawFall,0)}</b></div><div class="score"><span>Logit / boosting / forest</span><b>${pct(c.logit,0)} / ${pct(c.gradientBoosting,0)} / ${pct(c.randomForest,0)}</b></div><div class="score"><span>Banking-crisis link, Brier vs base (economies out)</span><b>${fmt(v.leaveOneCountryOut.brier,3)} vs ${fmt(v.leaveOneCountryOut.baseRateBrier,3)}</b></div><div class="score"><span>…eras out</span><b>${fmt(v.leaveOneEraOut.brier,3)} vs ${fmt(v.leaveOneEraOut.baseRateBrier,3)}</b></div><p>${tree.backtest.skillDisclosure}</p>`}
function renderSources(d){const input=$('#sourceSearch'),all=(d.references||[]).filter(x=>x.title);const draw=()=>{const q=input.value.toLowerCase(),rows=all.filter(x=>JSON.stringify(x).toLowerCase().includes(q));$('#sourceCount').textContent=rows.length+' verified references';$('#sourceList').innerHTML=rows.slice(0,80).map(x=>`<div class="source"><small>${x.year||''}</small><div><a href="${x.url||('https://doi.org/'+x.doi)}" target="_blank" rel="noopener">${x.title}</a><br><small>${(x.authors||[]).join?.(', ')||x.authors||''}</small></div><small>${x.type||''}</small></div>`).join('')};input.oninput=draw;draw()}

/* ---------- glossary, tooltip, citations */
function renderGlossary(){$('#glossList').innerHTML=GLOSS.slice().sort((a,b)=>a[2].localeCompare(b[2])).map(g=>`<div><dt>${g[2]}</dt><dd>${g[3]}</dd></div>`).join('')}
function glossarize(){
 const skip=new Set(['A','BUTTON','SELECT','OPTION','CITE','SCRIPT','STYLE','SVG','TEXTAREA','PRE','CODE','TH','DT','H1','H2','H3','H4','SUMMARY','INPUT','LABEL']);
 $$('main section').forEach(sec=>{if(['glossary','references','methodology','sources'].includes(sec.id))return;const used=new Set(),walker=document.createTreeWalker(sec,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  nodes.forEach(node=>{let p=node.parentNode,bad=false;while(p&&p!==sec){if(skip.has((p.tagName||'').toUpperCase())||(p.classList&&['term','stamp','kicker','eyebrow','chapter-no','tag','kind','guide','chips','legend','dots-legend'].some(c=>p.classList.contains(c)))){bad=true;break}p=p.parentNode}if(bad||!node.nodeValue.trim())return;
   let text=node.nodeValue,best=null;GLOSS.forEach(g=>{if(used.has(g[0]))return;const m=g[1].exec(text);if(m&&(!best||m.index<best.m.index))best={g,m}});if(!best)return;
   used.add(best.g[0]);const frag=document.createDocumentFragment(),i=best.m.index,t=best.m[0];frag.append(document.createTextNode(text.slice(0,i)));const s=el('span','term',t);s.tabIndex=0;s.dataset.def=best.g[3];s.dataset.title=best.g[2];frag.append(s,document.createTextNode(text.slice(i+t.length)));node.parentNode.replaceChild(frag,node)})})}
function initTip(){const tip=$('#tip');const show=t=>{tip.innerHTML=`<b>${t.dataset.title}</b><br>${t.dataset.def}`;tip.hidden=false;const r=t.getBoundingClientRect(),w=Math.min(320,innerWidth-24);tip.style.width=w+'px';let x=Math.max(12,Math.min(innerWidth-w-12,r.left+r.width/2-w/2));tip.style.left=x+'px';const h=tip.offsetHeight;tip.style.top=(r.top>h+20?r.top-h-10:r.bottom+10)+'px'};
 const hide=()=>{tip.hidden=true};document.addEventListener('mouseover',e=>{const t=e.target.closest('.term');if(t)show(t)});document.addEventListener('mouseout',e=>{if(e.target.closest('.term'))hide()});document.addEventListener('focusin',e=>{const t=e.target.closest('.term');if(t)show(t)});document.addEventListener('focusout',hide);document.addEventListener('click',e=>{const t=e.target.closest('.term');if(t)show(t);else hide()});document.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});addEventListener('scroll',hide,{passive:true})}
function numberCitations(){
 const order=[];$$('cite[data-k]').forEach(c=>c.dataset.k.split(',').forEach(k=>{if(!order.includes(k))order.push(k)}));
 const idx={};order.forEach((k,i)=>idx[k]=i+1);
 $$('cite[data-k]').forEach(c=>{const ks=c.dataset.k.split(',').sort((a,b)=>idx[a]-idx[b]);c.innerHTML='<sup>['+ks.map(k=>`<a href="#ref-${k}">${idx[k]}</a>`).join(', ')+']</sup>'});
 return {order,idx}}
const ST={'Data':'st-data','Fixed rule':'st-fixed','Estimated':'st-est','Calibrated':'st-cal','Assumed':'st-ass'};
function renderMethodology(m){
 const counts={};m.sections.forEach(s=>(s.tables||[]).forEach(t=>t.rows.forEach(r=>counts[r.status]=(counts[r.status]||0)+1)));
 $('#statusSummary').innerHTML=m.statusLegend.map(l=>`<div class="status-row"><span class="pill ${ST[l.status]}">${l.status}</span><b>${counts[l.status]||0}</b><span>${l.meaning}</span></div>`).join('')+`<p class="caveat">${Object.values(counts).reduce((a,b)=>a+b,0)} entries across ${m.sections.length} sections. Assumed entries are the parts of the model a reader should challenge first.</p>`;
 $('#methodSections').innerHTML=m.sections.map((s,i)=>`<details class="msec" ${i===0?'open':''}><summary><b>${s.title}</b></summary><p class="msum">${s.summary}</p>${s.equations?`<pre class="eq">${s.equations.map(e=>e.replace(/&/g,'&amp;').replace(/</g,'&lt;')).join('\n')}</pre>`:''}${(s.tables||[]).map(t=>`<h4>${t.title}</h4><div class="table-wrap mtable"><table><thead><tr><th>Parameter</th><th>Value</th><th>Status</th><th>How it was set</th><th>Source</th></tr></thead><tbody>${t.rows.map(r=>`<tr><td>${r.name}</td><td class="val">${r.value}</td><td><span class="pill ${ST[r.status]}">${r.status}</span></td><td>${r.how}</td><td>${r.cite.length?C(r.cite.join(',')):''}${r.src?`<code>${r.src}</code>`:''}</td></tr>`).join('')}</tbody></table></div>`).join('')}</details>`).join('')}
function renderReferences(cit,num){
 const by=Object.fromEntries(cit.items.map(i=>[i.key,i])),used=num.order.filter(k=>by[k]),rest=cit.items.filter(i=>!num.idx[i.key]);
 const auth=a=>{const x=(a||[]).filter(n=>!/^Institutional/.test(n));return x.length>3?x.slice(0,3).join(', ')+' et al.':x.join(', ')};
 const li=(i)=>`<li id="ref-${i.key}" data-kind="${i.kind}"><span class="ref-main">${auth(i.authors)?auth(i.authors)+' ':''}(${i.year}). <i>${i.title}</i>${i.venue?'. '+i.venue:''}${i.url?` · <a href="${i.url}" target="_blank" rel="noopener">${i.doi?'doi:'+i.doi:'link'}</a>`:''}</span><span class="ref-use"><em>${i.kind}</em> ${i.use}</span></li>`;
 $('#refList').innerHTML=used.map(k=>li(by[k])).join('')+rest.map(li).join('');
 $('#refIntro').textContent=`${used.length} sources are cited in the text${rest.length?`; ${rest.length} more are listed for completeness`:''}. Each entry says what the source is used for in this model. DOIs were checked against Crossref; data sources link to the provider.`;
 const kinds=[...new Set(cit.items.map(i=>i.kind))],f=$('#refFilter');
 f.innerHTML=['all',...kinds].map(k=>`<button class="chip" data-k="${k}">${k==='all'?'All':({data:'Data',method:'Statistics',theory:'Theory and evidence',benchmark:'Benchmarks'})[k]||k}</button>`).join('');
 f.onclick=e=>{const b=e.target.closest('button');if(!b)return;$$('#refList li').forEach(l=>l.style.display=(b.dataset.k==='all'||l.dataset.kind===b.dataset.k)?'':'none')}}

const canvas=$('#field'),ctx=canvas.getContext('2d');let pts=[];function resize(){canvas.width=innerWidth*devicePixelRatio;canvas.height=innerHeight*devicePixelRatio;pts=Array.from({length:40},()=>[Math.random()*canvas.width,Math.random()*canvas.height,Math.random()*.45+.1])}function anim(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='rgba(114,241,184,.14)';pts.forEach((p,i)=>{p[1]-=p[2];if(p[1]<0)p[1]=canvas.height;pts.slice(i+1).forEach(q=>{const d=Math.hypot(p[0]-q[0],p[1]-q[1]);if(d<220){ctx.globalAlpha=1-d/220;ctx.beginPath();ctx.moveTo(...p);ctx.lineTo(...q);ctx.stroke()}})});ctx.globalAlpha=1;if(!matchMedia('(prefers-reduced-motion: reduce)').matches)requestAnimationFrame(anim)}addEventListener('resize',resize);resize();anim();$('#theme').onclick=()=>document.documentElement.classList.toggle('light');
